// The RSS node emits one item per <item>. Most podcast hosts publish newest
// first, but that is not guaranteed, so sort by date and keep the newest
// entry that actually carries a playable audio enclosure.
const cfg = $('Config').first().json;
const items = $input.all().map((i) => i.json);
if (!items.length) {
  throw new Error('The feed at ' + cfg.feedUrl + ' returned no items. Check the URL in Config - it must be the RSS feed, not the show page.');
}

// rss-parser exposes <enclosure> as { url, length, type }. Some feeds only
// carry media:content or put the file on <link>, so probe those too before
// giving up on an episode.
const audioUrlOf = (it) => {
  const enc = it.enclosure;
  if (enc && typeof enc === 'object' && enc.url) {
    const type = String(enc.type || '');
    if (!type || /^audio\//i.test(type)) return String(enc.url);
  }
  if (typeof enc === 'string' && /^https?:/i.test(enc)) return enc;
  const media = it['media:content'] || it.mediaContent;
  const mUrl = media && (media.$ ? media.$.url : media.url);
  if (mUrl && /^https?:/i.test(String(mUrl))) return String(mUrl);
  if (typeof it.link === 'string' && /\.(mp3|m4a|aac|wav)(\?|$)/i.test(it.link)) return it.link;
  return null;
};

const dateOf = (it) => {
  const raw = it.isoDate || it.pubDate || it.date;
  const t = raw ? Date.parse(raw) : NaN;
  return Number.isFinite(t) ? t : 0;
};

// "2335" | "38:55" | "01:02:03" -> seconds
const durationOf = (raw) => {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return null;
  if (/^\d+$/.test(s)) return Number(s);
  const parts = s.split(':').map(Number);
  if (parts.some((n) => !Number.isFinite(n))) return null;
  return parts.reduce((acc, n) => acc * 60 + n, 0);
};

const withAudio = items.filter((it) => audioUrlOf(it));
if (!withAudio.length) {
  throw new Error('No episode in this feed has an audio enclosure (' + items.length + ' items checked). Some feeds are video-only or link straight to a player page; point feedUrl at a standard audio podcast RSS feed.');
}
withAudio.sort((a, b) => dateOf(b) - dateOf(a));
const it = withAudio[0];

const itunes = it.itunes || {};
const cover = String(cfg.coverImageOverride || '').trim()
  || String(itunes.image || it['itunes:image'] || it.image || '').trim();

// Item-level fields only: the RSS node hands back entries, not the channel,
// so the show name comes from Config when the item does not carry one.
const showName = String(cfg.showNameOverride || '').trim()
  || String(itunes.author || it.creator || it.author || '').trim()
  || 'The Podcast';

const when = dateOf(it) ? new Date(dateOf(it)) : new Date();
const dateLabel = when.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' }).toUpperCase();
const epNumber = itunes.episode ? String(itunes.episode).trim() : null;
const episodeChip = (epNumber ? 'EP ' + epNumber + ' - ' : '') + dateLabel;

// The Range cap is what keeps a 90-minute episode from being downloaded and
// transcribed in full. MP3/AAC decode fine from a truncated head.
const requestedMB = Number(cfg.maxTranscribeMB ?? 4);
const maxAudioBytes = Number(cfg.maxAudioBytes ?? 5242880);
if (!Number.isFinite(requestedMB) || requestedMB <= 0 || !Number.isFinite(maxAudioBytes) || maxAudioBytes < 1) {
  throw new Error('maxTranscribeMB and maxAudioBytes must be positive numbers in Config.');
}
// The same file is uploaded for rendering, so respect its audio-asset limit too.
const maxBytes = Math.floor(Math.min(requestedMB * 1048576, 25 * 1048576, maxAudioBytes));

return [{
  json: {
    found: true,
    showName: showName,
    episodeTitle: String(it.title || '').replace(/\s+/g, ' ').trim(),
    episodeChip: episodeChip,
    episodeLink: String(it.link || ''),
    coverUrl: cover,
    audioUrl: audioUrlOf(it),
    episodeSeconds: durationOf(itunes.duration),
    rangeHeader: 'bytes=0-' + (maxBytes - 1),
    maxBytes: maxBytes,
    episodesChecked: items.length,
  },
}];

// Turns one ElevenLabs Scribe response into (a) the word list every later
// node reads and (b) the numbered transcript the model picks moments from.
// The downloaded audio is re-attached so the next node can upload the EXACT
// bytes that were transcribed - that is what makes caption timing exact.
const cfg = $('Config').first().json;
const res = $input.first().json;

// Scribe returns { text, words: [{ text, start, end, type }] }. Anything else
// is an error payload or a plan/quota message, so say so plainly.
const raw = Array.isArray(res && res.words) ? res.words : null;
if (!raw) {
  throw new Error(
    'ElevenLabs Scribe returned no word timings. Check the xi-api-key credential and your speech-to-text quota, and make sure timestamps_granularity is "word". Response: ' +
      JSON.stringify(res).slice(0, 400)
  );
}

// Curly quotes and dashes make caption chunks look broken and break naive
// sentence detection, so normalise to ASCII once, here.
const toAscii = (s) => String(s)
  .replace(/[\u2018\u2019\u02BC]/g, "'")
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2013\u2014]/g, '-')
  .replace(/\u2026/g, '...')
  .replace(/\s+/g, ' ')
  .trim();

const words = [];
for (const w of raw) {
  if (!w) continue;
  if (w.type && w.type !== 'word') continue; // spacing / audio_event entries
  const text = toAscii(w.text || '');
  const start = Number(w.start);
  const end = Number(w.end);
  if (!text || !Number.isFinite(start) || !Number.isFinite(end)) continue;
  words.push({ text: text, start: start, end: end });
}
if (words.length < 40) {
  throw new Error('Scribe only recognised ' + words.length + ' words in the downloaded audio. The episode may start with music, or the Range download may have been too small - raise maxTranscribeMB in Config.');
}

// Clips can only be cut inside the window the platform can seek into:
// audioBegin/audioEnd are capped at the plan maxDuration (300 s on the free
// plan), and we can only cut what was actually transcribed.
const windowEnd = Math.min(
  Number(cfg.clipWindowSeconds || 300),
  words[words.length - 1].end
);
const windowStart = Math.max(0, Number(cfg.skipIntroSeconds || 0));
const eligible = words.filter((w) => w.start >= windowStart && w.end <= windowEnd);
if (eligible.length < 40) {
  throw new Error('Only ' + eligible.length + ' words fall inside the clip window (' + windowStart + 's to ' + Math.round(windowEnd) + 's). Lower skipIntroSeconds or raise clipWindowSeconds.');
}

// A numbered transcript: every line starts with the index of its first word,
// so the model can answer in word indices instead of timestamps it cannot see.
const PER_LINE = 10;
const lines = [];
for (let i = 0; i < eligible.length; i += PER_LINE) {
  lines.push('#' + i + ' ' + eligible.slice(i, i + PER_LINE).map((w) => w.text).join(' '));
}

const clipCount = Math.max(1, Math.min(3, Number(cfg.clipCount || 2)));
const clipSeconds = Math.max(10, Math.min(90, Number(cfg.clipSeconds || 30)));

const promptText = [
  'Below is a numbered transcript of the opening of a podcast episode. Each line',
  'starts with #N, the index of its first word.',
  '',
  'Pick the ' + clipCount + ' most quotable, self-contained moments to cut as short social',
  'clips of about ' + clipSeconds + ' seconds each (roughly ' + Math.round(clipSeconds * 2.9) + ' words).',
  '',
  'Rules:',
  '- Each moment must stand alone with no context from the rest of the episode.',
  '- Start on a sentence boundary. Never start mid-sentence.',
  '- Avoid ad reads, intros, outros, housekeeping and cross-promotion.',
  '- The moments must not overlap and should come from different parts.',
  '- hook: at most 8 words, written as a scroll-stopping on-screen line. Do not',
  '  use quotation marks, emoji or hashtags. Sentence case.',
  '- whyItSlaps: one short sentence, for the human reviewing the run.',
  '',
  'Return JSON only, exactly this shape:',
  '{"clips":[{"startWord":0,"endWord":80,"hook":"...","whyItSlaps":"..."}]}',
  '',
  'TRANSCRIPT',
].concat(lines).join('\n');

return [{
  json: {
    words: eligible,
    allWords: words.length,
    eligibleWords: eligible.length,
    windowStart: windowStart,
    windowEnd: Math.round(windowEnd * 100) / 100,
    transcribedSeconds: Math.round(words[words.length - 1].end * 100) / 100,
    clipCount: clipCount,
    clipSeconds: clipSeconds,
    promptText: promptText,
  },
  // Same bytes in, same bytes out: the upload node needs the file that was
  // transcribed, not a second download that a dynamic-ad host would change.
  binary: $('Fetch episode audio').first().binary,
}];

// Turns the model's word indices into real clip windows: exact start/end
// times plus the word timings for that slice. Emits ONE ITEM PER CLIP, so
// everything downstream runs per clip.
const cfg = $('Config').first().json;
const t = $('Read transcript').first().json;
const words = t.words;
const res = $input.first().json;

const clipSeconds = t.clipSeconds;
const minSeconds = Math.max(5, Math.min(clipSeconds, Number(cfg.minClipSeconds || 18)));
const windowEnd = t.windowEnd;

const content = res && res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
let picked = [];
if (content) {
  let parsed = null;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    const m = /\{[\s\S]*\}/.exec(content);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
  }
  if (parsed && Array.isArray(parsed.clips)) picked = parsed.clips;
}

// The model is a suggestion engine, not a source of truth: every index is
// clamped, every window is re-cut to the configured length, and a run still
// produces clips if the model returns nothing usable.
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
const stripQuotes = (s) => clean(s).replace(/^["\u201C\u2018\u0027]+|["\u201D\u2019\u0027]+$/g, '');
const endsSentence = (w) => /[.!?]$/.test(w.text);

// Walk forward from startIdx until the target length is reached, preferring
// the last sentence end at or before the target so clips do not stop
// mid-thought.
function cutFrom(startIdx) {
  const start = words[startIdx].start;
  let target = startIdx;
  let lastSentence = -1;
  for (let i = startIdx; i < words.length; i += 1) {
    const len = words[i].end - start;
    if (len > clipSeconds) break;
    target = i;
    if (endsSentence(words[i]) && len >= minSeconds) lastSentence = i;
  }
  const endIdx = lastSentence >= 0 ? lastSentence : target;
  return { startIdx: startIdx, endIdx: endIdx };
}

// Prefer starting on the first word of a sentence, but never step back past
// floorIdx (the word right after the previous accepted clip).
function snapToSentenceStart(idx, floorIdx) {
  for (let i = idx; i > Math.max(floorIdx, idx - 25); i -= 1) {
    if (i === 0) return 0;
    if (endsSentence(words[i - 1])) return i;
  }
  return Math.max(floorIdx, idx);
}

// A hook built straight from the transcript should not trail off on a
// stopword ("...worth more than every").
const TRAILING = ['and', 'but', 'or', 'so', 'that', 'the', 'a', 'an', 'of', 'to', 'for', 'with', 'than', 'is', 'was', 'in', 'on', 'at', 'as', 'it'];
function hookFromWords(from) {
  const out = [];
  for (let i = from; i < Math.min(words.length, from + 9); i += 1) {
    out.push(words[i].text.replace(/[,;:]+$/, ''));
    if (endsSentence(words[i])) break;
  }
  while (out.length > 3 && TRAILING.indexOf(out[out.length - 1].toLowerCase().replace(/[^a-z]/g, '')) !== -1) out.pop();
  return out.slice(0, 8).join(' ').replace(/[.,;:!?]+$/, '');
}

const cuts = [];
let nextFree = 0;

// Cut the picks in transcript order and never let a clip start before the
// previous one ended. A clip always runs to the configured length, so taking
// the picks out of order would let clip 1 swallow the start of clip 2 and
// throw away a perfectly good moment.
const ordered = picked
  .filter((p) => p && Number.isFinite(Number(p.startWord)))
  .sort((a, b) => Number(a.startWord) - Number(b.startWord));

for (const p of ordered) {
  if (cuts.length >= t.clipCount) break;
  const wanted = Math.max(nextFree, Math.round(Number(p.startWord)));
  if (wanted > words.length - 2) continue;
  const cut = cutFrom(snapToSentenceStart(wanted, nextFree));
  const secs = words[cut.endIdx].end - words[cut.startIdx].start;
  if (secs < minSeconds) continue;
  nextFree = cut.endIdx + 1;
  cuts.push({
    startIdx: cut.startIdx,
    endIdx: cut.endIdx,
    hook: stripQuotes(p.hook).split(/\s+/).filter(Boolean).slice(0, 8).join(' ').slice(0, 80) || hookFromWords(cut.startIdx),
    whyItSlaps: clean(p.whyItSlaps).slice(0, 200),
    source: 'model',
  });
}

// Fallback: split the transcript into clipCount blocks and start a clip at
// the top of each one, never before the previous clip ended. A run never
// fails just because the model had an off day.
let slot = cuts.length;
let guard = 0;
while (cuts.length < t.clipCount && guard < t.clipCount * 4) {
  guard += 1;
  const block = Math.floor((words.length * Math.min(slot, t.clipCount - 1)) / t.clipCount);
  const idx = Math.min(words.length - 2, Math.max(nextFree, block));
  slot += 1;
  const cut = cutFrom(snapToSentenceStart(idx, nextFree));
  const secs = words[cut.endIdx].end - words[cut.startIdx].start;
  if (secs < minSeconds) {
    if (idx >= words.length - 2) break;
    continue;
  }
  nextFree = cut.endIdx + 1;
  cuts.push({
    startIdx: cut.startIdx,
    endIdx: cut.endIdx,
    hook: hookFromWords(cut.startIdx),
    whyItSlaps: 'Fallback pick - the model did not return a usable moment for this slot.',
    source: 'fallback',
  });
}

if (!cuts.length) {
  throw new Error('Could not cut a single clip of at least ' + minSeconds + 's from the transcribed window. Raise maxTranscribeMB, or lower minClipSeconds/clipSeconds in Config.');
}

cuts.sort((a, b) => a.startIdx - b.startIdx);

return cuts.map((c, i) => {
  const slice = words.slice(c.startIdx, c.endIdx + 1);
  const startSeconds = Math.round(slice[0].start * 100) / 100;
  const endSeconds = Math.min(windowEnd, Math.round(slice[slice.length - 1].end * 100) / 100);
  return {
    json: {
      index: i + 1,
      hook: c.hook,
      whyItSlaps: c.whyItSlaps,
      source: c.source,
      startSeconds: startSeconds,
      endSeconds: endSeconds,
      seconds: Math.round((endSeconds - startSeconds) * 100) / 100,
      words: slice,
    },
    pairedItem: { item: 0 },
  };
});

// Builds ONE audiogram payload per selected moment: the code node emits one
// item per clip, and everything downstream (validate -> render -> watch) runs
// per item.
//
// Design adapted from Zvid's library: img-social-podcast-quote (equalizer
// motif, chip row, serif pull-quote on near-black) and social-podcast-clip
// (cover-art composition, accent CTA rail).
//
// The audio is ONE uploaded asset - the exact bytes that were transcribed -
// and each clip seeks into it with audioBegin/audioEnd. Because the captions
// are measured against those same bytes, word timings can never drift.

// --- small helpers ---------------------------------------------------------
function escapeHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

function clean(v) {
  return String(v == null ? '' : v).replace(/\s+/g, ' ').trim();
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

// The render API's project-name pattern is strict ASCII: /^[a-zA-Z0-9_\- ]+$/.
// Episode titles are routinely not, so slug hard and keep a fallback.
function sanitizeProjectName(s) {
  const out = String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
  return out || 'podcast-clip';
}

// 18.4 -> "0:18", 2335 -> "38:55"
function clock(totalSeconds) {
  const t = Math.max(0, Math.floor(Number(totalSeconds) || 0));
  const h = Math.floor(t / 3600);
  const m = Math.floor((t % 3600) / 60);
  const s = t % 60;
  const pad = (n) => (n < 10 ? '0' + n : String(n));
  return h > 0 ? h + ':' + pad(m) + ':' + pad(s) : m + ':' + pad(s);
}

function hexRgb(hex) {
  const m = /^#?([0-9a-fA-F]{6})$/.exec(String(hex).trim());
  if (!m) return '255,255,255';
  const n = parseInt(m[1], 16);
  return ((n >> 16) & 255) + ',' + ((n >> 8) & 255) + ',' + (n & 255);
}

// Largest size from the ramp whose estimated wrap stays inside maxLines.
// avgEm is the average glyph advance in em for the face (DM Serif Display
// reads ~0.50em mixed case, Space Grotesk ~0.62em uppercase). Errs towards
// "one size smaller" so nothing ever clips.
function fitSize(text, sizes, boxWidth, maxLines, avgEm) {
  const words = String(text).split(/\s+/).filter(Boolean);
  const longest = Math.max.apply(null, words.map((w) => w.length).concat([1]));
  const countLines = (size) => {
    const per = Math.max(4, Math.floor(boxWidth / (size * avgEm)));
    let lines = 1;
    let used = 0;
    for (let j = 0; j < words.length; j += 1) {
      const w = words[j];
      const need = used === 0 ? w.length : used + 1 + w.length;
      if (need <= per) { used = need; continue; }
      lines += 1;
      used = Math.min(w.length, per);
    }
    return lines;
  };
  for (let i = 0; i < sizes.length; i += 1) {
    const size = sizes[i];
    const lines = countLines(size);
    if (lines <= maxLines && longest * size * avgEm <= boxWidth) {
      return { size: size, lines: lines };
    }
  }
  const last = sizes[sizes.length - 1];
  return { size: last, lines: countLines(last) };
}

// Single-line run width in px, used to size the chips (SVG/inline pills do not
// wrap, so anything wider than its box would spill off canvas).
function runWidth(text, fontPx, letterSpacing, avgEm) {
  return Math.ceil(String(text).length * (fontPx * avgEm + letterSpacing));
}

// Largest font whose single line fits maxWidth; truncates with an ellipsis
// only after the smallest size still overflows.
function fitRun(text, sizes, maxWidth, letterSpacing, avgEm) {
  const t = String(text);
  for (let i = 0; i < sizes.length; i += 1) {
    if (runWidth(t, sizes[i], letterSpacing, avgEm) <= maxWidth) {
      return { text: t, size: sizes[i], width: runWidth(t, sizes[i], letterSpacing, avgEm) };
    }
  }
  const size = sizes[sizes.length - 1];
  const per = Math.max(4, Math.floor(maxWidth / (size * avgEm + letterSpacing)));
  const cut = t.slice(0, Math.max(1, per - 1)).replace(/[\s\u2026.,;:-]+$/, '') + '\u2026';
  return { text: cut, size: size, width: runWidth(cut, size, letterSpacing, avgEm) };
}

// --- the build -------------------------------------------------------------
function buildClipProject(config, episode, clip, audioUrl) {
  const cfg = config || {};

  // ---- palette + type ----------------------------------------------------
  const ink = clean(cfg.inkColor) || '#0B0A12';
  const panel = clean(cfg.panelColor) || '#17141F';
  const offWhite = clean(cfg.textColor) || '#F2EFFA';
  const muted = clean(cfg.mutedColor) || '#8E88A6';
  const accent = clean(cfg.brandAccent) || '#2DD4BF';
  const hookFont = clean(cfg.hookFont) || 'DM Serif Display';
  const uiFont = clean(cfg.uiFont) || 'Space Grotesk';
  const captionFont = clean(cfg.captionFont) || 'Inter';
  const inkRgb = hexRgb(ink);
  const paperRgb = hexRgb(offWhite);
  const accentRgb = hexRgb(accent);

  // ---- content -----------------------------------------------------------
  const showName = (clean(cfg.showNameOverride) || clean(episode.showName) || 'The Podcast').toUpperCase();
  const episodeChip = clean(episode.episodeChip) || 'NEW EPISODE';
  const handle = clean(cfg.handle);
  const listenLine = clean(cfg.listenLine);
  const coverUrl = clean(cfg.coverImageOverride) || clean(episode.coverUrl);
  if (!coverUrl) throw new Error('No cover art: the feed carried no episode/show image and coverImageOverride is empty in Config.');
  if (!audioUrl) throw new Error('No audio URL: the episode upload did not return a CDN url.');

  const hook = clean(clip.hook) || clean(episode.episodeTitle) || 'Listen to this';
  const clipStart = round2(Math.max(0, Number(clip.startSeconds)));
  const clipEnd = round2(Number(clip.endSeconds));
  const seconds = round2(Math.max(4, clipEnd - clipStart));
  if (!Number.isFinite(seconds) || seconds <= 0) {
    throw new Error('Clip ' + clip.index + ' has no usable length (start ' + clipStart + 's, end ' + clipEnd + 's).');
  }

  // ---- chips -------------------------------------------------------------
  // The two chips share the top row: the show pill starts at x=70, the episode
  // pill ends at x=1010, and a 30px gutter separates them. Sizing the episode
  // pill first leaves an exact budget for the show name.
  const epFit = fitRun(episodeChip.toUpperCase(), [22, 20, 18], 300, 3, 0.62);
  const epChipW = Math.min(340, epFit.width + 56);
  const showBudget = 1010 - epChipW - 30 - 70 - 74; // 74 = dot + pill padding
  const showFit = fitRun(showName, [26, 23, 20, 18], Math.max(180, showBudget), 4, 0.62);

  // ---- hook --------------------------------------------------------------
  // The hook is centred in a fixed band, so one line and three lines both stay
  // clear of the cover art above and of the caption zone below (which grows
  // upwards from a fixed bottom edge).
  const hookFit = fitSize(hook, [72, 64, 56, 50, 44], 920, 3, 0.50);

  // ---- equalizer ---------------------------------------------------------
  // 25 bars. Every animation period divides the 2.4s capture window exactly,
  // so the captured loop repeats seamlessly for the whole clip instead of
  // capturing hundreds of near-identical frames.
  const EQ_H = [30, 52, 40, 78, 58, 96, 44, 68, 34, 88, 56, 96, 72, 46, 90, 62, 38, 84, 50, 96, 42, 66, 36, 54, 32];
  const EQ_D = [1.2, 0.8, 0.6, 1.2, 0.8, 2.4, 0.6, 1.2, 0.8, 2.4, 0.6, 1.2, 0.8, 0.6, 2.4, 1.2, 0.8, 2.4, 0.6, 1.2, 0.8, 0.6, 1.2, 0.8, 0.6];
  let eqBars = '';
  let eqCss = '';
  for (let i = 0; i < EQ_H.length; i += 1) {
    eqBars += '<i></i>';
    eqCss += '.eq i:nth-child(' + (i + 1) + '){height:' + EQ_H[i] + 'px;animation-duration:' + EQ_D[i] + 's;animation-delay:-' + round2((i * 0.17) % 2.4) + 's}';
  }
  const equalizerCss =
    '.eq{display:flex;align-items:flex-end;justify-content:center;gap:19px;width:720px;height:96px}' +
    '.eq i{display:block;width:10px;border-radius:6px;background:linear-gradient(180deg,rgba(' + accentRgb + ',1) 0%,rgba(' + accentRgb + ',0.35) 100%);' +
    'transform-origin:50% 100%;animation-name:eqb;animation-timing-function:ease-in-out;animation-iteration-count:infinite}' +
    '@keyframes eqb{0%,100%{transform:scaleY(0.16)}50%{transform:scaleY(1)}}' +
    eqCss;

  // ---- background --------------------------------------------------------
  // The cover art doubles as the backdrop: blurred and dimmed, so every episode
  // carries its own colour without a stock-photo lottery.
  //
  // Both cover images go through the BROWSER (an <img> inside a TEXT element)
  // rather than an IMAGE element. Podcast feeds hand out artwork URLs like
  // `.../format/jpg/?url=http%3A%2F%2F...` - no file extension and percent
  // signs in the path - and ffmpeg's image2 demuxer reads those as a numbered
  // sequence pattern and fails the whole render. Chromium does not care, and it
  // gives true object-fit cropping, rounded corners and a real CSS blur.
  const visuals = [];
  visuals.push({
    type: 'TEXT', x: 540, y: 960, width: 1080, height: 1920, anchor: 'center-center',
    track: 0, enterBegin: 0, exitEnd: seconds,
    style: { fontFamily: uiFont, color: offWhite },
    html:
      "<div style='width:1080px; height:1920px; overflow:hidden;'>" +
      "<img src='" + escapeHtml(coverUrl) + "' alt='' style='display:block; width:1240px; height:2200px; margin:-140px -80px; object-fit:cover; filter:blur(40px) saturate(0.42) brightness(0.44);'>" +
      '</div>',
  });

  visuals.push({
    type: 'SVG', width: 1080, height: 1920, x: 540, y: 960, anchor: 'center-center',
    track: 1, enterBegin: 0, exitEnd: seconds,
    svg:
      "<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>" +
      "<defs><linearGradient id='pacShade' x1='0' y1='0' x2='0' y2='1'>" +
      "<stop offset='0' stop-color='" + ink + "' stop-opacity='0.86'/>" +
      "<stop offset='0.42' stop-color='" + ink + "' stop-opacity='0.66'/>" +
      "<stop offset='1' stop-color='" + ink + "' stop-opacity='0.95'/></linearGradient>" +
      "<radialGradient id='pacGlow' cx='0.5' cy='0.25' r='0.62'>" +
      "<stop offset='0' stop-color='" + accent + "' stop-opacity='0.20'/>" +
      "<stop offset='1' stop-color='" + accent + "' stop-opacity='0'/></radialGradient></defs>" +
      "<rect width='1080' height='1920' fill='url(#pacShade)'/>" +
      "<rect width='1080' height='1920' fill='url(#pacGlow)'/>" +
      "<rect x='44' y='44' width='992' height='1832' rx='34' fill='none' stroke='rgba(" + paperRgb + ",0.09)' stroke-width='1.5'/>" +
      '</svg>',
  });

  // ---- cover art card ----------------------------------------------------
  // NOTE: no `resize` on inset media. `resize` overwrites width/height with
  // CANVAS-relative dimensions, so a "500x500 cover" card silently becomes a
  // full-bleed image. Explicit width/height already centre-crop the source.
  //
  // The card is an <img> inside a TEXT element: object-fit gives a true
  // centre-crop for feeds whose artwork is not perfectly square, and the
  // wrapper carries the accent halo, the accent ring and the drop shadow in
  // ONE element. The halo used to be its own 700x700 SVG behind the card -
  // two elements sharing a region is exactly what the layout linter flags, and
  // a CSS radial-gradient at the same radius and stops is pixel-equivalent.
  visuals.push({
    type: 'TEXT', x: 540, y: 470, width: 700, height: 700, anchor: 'center-center',
    track: 2, enterBegin: 0, enterEnd: 0.7, enterAnimation: 'fade', exitEnd: seconds,
    style: { fontFamily: uiFont, color: offWhite },
    html:
      "<div style='width:700px; height:700px; display:flex; align-items:center; justify-content:center; " +
      'background:radial-gradient(circle 350px at 50% 50%, rgba(' + accentRgb + ',0.34) 0px, rgba(' + accentRgb + ",0.34) 119px, rgba(" + accentRgb + ",0) 350px);'>" +
      "<div style='width:480px; height:480px; border-radius:44px; overflow:hidden; border:2px solid rgba(" + accentRgb + ",0.55); box-shadow:0 34px 90px rgba(0,0,0,0.72);'>" +
      "<img src='" + escapeHtml(coverUrl) + "' alt='' style='display:block; width:100%; height:100%; object-fit:cover;'>" +
      '</div></div>',
  });

  // ---- chip row ----------------------------------------------------------
  visuals.push({
    type: 'TEXT', x: 70, y: 148, anchor: 'center-left', track: 3,
    enterBegin: 0.15, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: seconds,
    style: { fontFamily: uiFont, color: accent },
    html:
      "<div style='display:inline-block; background:rgba(" + accentRgb + ",0.13); border:1.5px solid rgba(" + accentRgb + ",0.5); border-radius:999px; padding:14px 26px; white-space:nowrap; color:" + accent + "; font-size:" + showFit.size + "px; font-weight:700; letter-spacing:4px;'>" +
      "<span style='display:inline-block; width:11px; height:11px; border-radius:99px; background:" + accent + "; margin-right:14px;'></span>" +
      escapeHtml(showFit.text) + '</div>',
  });

  visuals.push({
    type: 'TEXT', x: 1010, y: 148, anchor: 'center-right', track: 3,
    enterBegin: 0.25, enterEnd: 0.7, enterAnimation: 'fade', exitEnd: seconds,
    style: { fontFamily: uiFont, color: muted },
    html:
      "<div style='display:inline-block; background:rgba(" + paperRgb + ",0.07); border:1px solid rgba(" + paperRgb + ",0.16); border-radius:999px; padding:14px 24px; white-space:nowrap; color:" + muted + "; font-size:" + epFit.size + "px; font-weight:700; letter-spacing:3px;'>" +
      escapeHtml(epFit.text) + '</div>',
  });

  // ---- equalizer ---------------------------------------------------------
  // No enterAnimation on this one: a captured-animation element combined with
  // an enter/exit xfade is the one combination the renderer has historically
  // frozen on frame 0, and the bars are the proof the clip is playing.
  //
  // y=872 puts the 96px band 4px clear of the cover card's 700px box (which
  // ends at y=820) - overlapping boxes are a layout-lint warning even when the
  // ink inside them never touches.
  visuals.push({
    type: 'TEXT', x: 540, y: 872, width: 720, height: 96, anchor: 'center-center',
    track: 3, enterBegin: 0, exitEnd: seconds,
    style: { fontFamily: uiFont, color: accent },
    html: "<div class='eq'>" + eqBars + '</div>',
    customCode: { animationDuration: 2.4, css: equalizerCss },
  });

  // ---- hook --------------------------------------------------------------
  visuals.push({
    type: 'TEXT', x: 540, y: 1140, width: 920, anchor: 'center-center', track: 4,
    enterBegin: 0.45, enterEnd: 1.15, enterAnimation: 'smoothup', exitEnd: seconds,
    style: { fontFamily: hookFont, color: offWhite },
    html:
      "<div style='text-align:center; color:" + offWhite + '; font-size:' + hookFit.size + "px; line-height:1.16; letter-spacing:-0.005em; text-shadow:0 6px 30px rgba(" + inkRgb + ",0.7);'>" +
      escapeHtml(hook) + '</div>',
  });

  visuals.push({
    type: 'SVG', width: 120, height: 4, x: 540, y: 1330, anchor: 'center-center',
    track: 4, enterBegin: 0.9, enterEnd: 1.4, enterAnimation: 'circleopen', exitEnd: seconds,
    svg: "<svg width='120' height='4' viewBox='0 0 120 4' xmlns='http://www.w3.org/2000/svg'><rect width='120' height='4' rx='2' fill='" + accent + "' fill-opacity='0.75'/></svg>",
  });

  // ---- player chrome -----------------------------------------------------
  // Timestamps read like a player: where this excerpt sits in the episode on
  // the left, the episode's own length on the right when the feed declared one.
  const epSeconds = Number(episode.episodeSeconds);
  const rightLabel = Number.isFinite(epSeconds) && epSeconds > clipEnd
    ? clock(epSeconds)
    : clock(clipEnd);
  visuals.push({
    type: 'TEXT', x: 540, y: 1600, width: 1040, anchor: 'center-center', track: 5,
    enterBegin: 1.2, enterEnd: 1.7, enterAnimation: 'fade', exitEnd: seconds,
    style: { fontFamily: uiFont, color: muted },
    html:
      "<div style='display:flex; justify-content:space-between; width:1040px; color:" + muted + "; font-size:23px; font-weight:600; letter-spacing:3px;'>" +
      '<span>' + escapeHtml(clock(clipStart)) + '</span><span>' + escapeHtml(rightLabel) + '</span></div>',
  });

  // The rail is static; the accent bar rides a full-width `wiperight` enter
  // animation that spans the whole clip, so the reveal IS the progress bar -
  // no captured frames, exact to the frame, free.
  visuals.push({
    type: 'SVG', width: 1080, height: 6, x: 540, y: 1650, anchor: 'center-center',
    track: 5, enterBegin: 0, exitEnd: seconds,
    svg: "<svg width='1080' height='6' viewBox='0 0 1080 6' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='6' fill='rgba(" + paperRgb + ",0.14)'/></svg>",
  });

  visuals.push({
    type: 'SVG', width: 1080, height: 6, x: 540, y: 1650, anchor: 'center-center',
    track: 6, enterBegin: 0, enterEnd: seconds, enterAnimation: 'wiperight', exitEnd: seconds,
    svg: "<svg width='1080' height='6' viewBox='0 0 1080 6' xmlns='http://www.w3.org/2000/svg'><rect width='1080' height='6' fill='" + accent + "'/></svg>",
  });

  // ---- footer ------------------------------------------------------------
  // One line when both parts fit, two when they do not: a 46-character handle
  // beside a sentence wraps mid-phrase and reads like a bug.
  const handleFit = handle ? fitRun(handle, [28, 25, 22, 20], 960, 1, 0.55) : null;
  const listenFit = listenLine ? fitRun(listenLine, [24, 22, 20, 18], 960, 1, 0.52) : null;
  const oneLine = handleFit && listenFit
    ? handleFit.width + listenFit.width + 60 <= 940
    : true;
  const footerParts = [];
  if (handleFit) {
    footerParts.push("<span style='color:" + offWhite + '; font-size:' + handleFit.size + "px; font-weight:700;'>" + escapeHtml(handleFit.text) + '</span>');
  }
  if (listenFit) {
    const sep = oneLine && handleFit
      ? "<span style='color:rgba(" + paperRgb + ",0.32);'> &#183; </span>"
      : '<br>';
    footerParts.push(sep + "<span style='color:" + muted + '; font-size:' + listenFit.size + "px; font-weight:500;'>" + escapeHtml(listenFit.text) + '</span>');
  }
  if (footerParts.length) {
    visuals.push({
      type: 'TEXT', x: 540, y: 1706, width: 960, anchor: 'top-center', track: 5,
      enterBegin: 1.1, enterEnd: 1.6, enterAnimation: 'fade', exitEnd: seconds,
      style: { fontFamily: uiFont, color: muted },
      html: "<div style='text-align:center; line-height:1.5; color:" + muted + "; letter-spacing:2px;'>" + footerParts.join('') + '</div>',
    });
  }

  // ---- captions ----------------------------------------------------------
  // Word timings arrive in EPISODE time; the timeline starts at the clip's
  // first word, so everything shifts by clipStart. Cues outside the clip are
  // dropped and the last cue is clamped to the clip end.
  const perCue = Math.max(1, Math.min(8, Number(cfg.captionWordsPerCue == null ? 4 : cfg.captionWordsPerCue)));
  const words = Array.isArray(clip.words) ? clip.words : [];
  const rel = [];
  for (let i = 0; i < words.length; i += 1) {
    const w = words[i];
    const s = round2(Number(w.start) - clipStart);
    const e = round2(Number(w.end) - clipStart);
    const text = clean(w.text);
    if (!text) continue;
    if (!Number.isFinite(s) || !Number.isFinite(e)) continue;
    if (e <= 0 || s >= seconds) continue;
    rel.push({ start: Math.max(0, s), end: Math.min(seconds, Math.max(s + 0.05, e)), text: text });
  }

  const captions = [];
  const maxCues = 200;
  for (let i = 0; i < rel.length && captions.length < maxCues; i += perCue) {
    const chunk = rel.slice(i, i + perCue);
    captions.push({
      start: chunk[0].start,
      end: chunk[chunk.length - 1].end,
      text: chunk.map((w) => w.text).join(' '),
      words: chunk.map((w) => ({ start: w.start, end: w.end, text: w.text })),
    });
  }

  // In box modes the chip behind the spoken word is drawn first and the
  // outline lands on top of it, so box modes get a thin outline plus padding;
  // every other mode recolours the spoken word and keeps the heavy stroke.
  //
  // The chip MUST carry a corner radius. Without one the renderer falls back
  // to libass' square BorderStyle box, and libass ignores a mid-line
  // BorderStyle switch - the chip never paints and the dark active word ends
  // up invisible on the dark backdrop. A radius routes the chip through the
  // engine's drawn rounded-box path, which paints it for real.
  const BOX_MODES = ['highlight'];
  const animation = clean(cfg.captionAnimation) || 'karaoke';
  const usesBox = BOX_MODES.indexOf(animation) !== -1;
  const strokeWidth = Math.max(0, Number(cfg.captionStrokeWidth == null ? 6 : cfg.captionStrokeWidth));
  const captionSize = Math.max(24, Math.min(96, Number(cfg.captionSize == null ? 62 : cfg.captionSize)));

  const subtitle = captions.length
    ? {
      captions: captions,
      animation: animation,
      activeWord: usesBox ? { color: ink, background: accent, radius: 12 } : { color: accent },
      font: { family: captionFont, size: captionSize, color: '#FFFFFF', bold: true, transform: 'uppercase' },
      stroke: { color: '#000000', width: usesBox ? Math.min(strokeWidth, 2) : strokeWidth },
      position: 'bottom-center',
      margin: { x: 90, y: 450 },
      maxWordsPerLine: perCue,
    }
    : null;
  // 8px of padding, not 14: the padding is also the chip's horizontal bleed,
  // and a space at this type size is ~17px, so anything larger makes the chip
  // touch the words on either side.
  if (usesBox && subtitle) subtitle.background = { padding: 8, color: '#000000', opacity: 0.0 };

  // ---- payload -----------------------------------------------------------
  const safeName = sanitizeProjectName('podcast clip ' + clip.index + ' ' + (episode.episodeTitle || showName));

  // `resolution: 'custom'` with an explicit 1080x1920 renders identically to the
  // `instagram-reel` preset (the engine resolves the preset to the same two
  // numbers). It is spelled out because the layout linter only knows the canvas
  // when it is stated: with a named preset it cannot tell a deliberate
  // full-bleed backdrop from two content boxes fighting over the same region,
  // and every layer in this design sits on top of a full-bleed backdrop.
  const payload = {
    name: safeName,
    resolution: 'custom',
    width: 1080,
    height: 1920,
    frameRate: Number(cfg.frameRate == null ? 30 : cfg.frameRate),
    backgroundColor: ink,
    outputFormat: 'mp4',
    scenes: [{ id: 'clip', duration: seconds, backgroundColor: panel, visuals: visuals }],
    // NOTE: no `track` on audio entries - the render API rejects audios[].track.
    // audioBegin/audioEnd seek inside the uploaded episode audio, so one upload
    // serves every clip and the captions cannot drift from the sound.
    audios: [{ src: audioUrl, volume: 1, enter: 0, exit: seconds, audioBegin: clipStart, audioEnd: clipEnd }],
  };
  if (subtitle) payload.subtitle = subtitle;

  return {
    payload: payload,
    meta: {
      clipIndex: clip.index,
      hook: hook,
      whyItSlaps: clean(clip.whyItSlaps),
      momentSource: clean(clip.source) || 'model',
      showName: showName,
      episodeTitle: clean(episode.episodeTitle),
      episodeChip: epFit.text,
      clipStart: clipStart,
      clipEnd: clipEnd,
      clipSeconds: seconds,
      startLabel: clock(clipStart),
      captionCount: captions.length,
      captionWords: rel.length,
      hookSize: hookFit.size,
      hookLines: hookFit.lines,
      showChipSize: showFit.size,
      showChipTruncated: showFit.text !== showName,
      coverUrl: coverUrl,
      audioUrl: audioUrl,
    },
  };
}

// === n8n glue ===
const config = $('Config').first().json;
const episode = $('Pick latest episode').first().json;

// The upload node returns { upload: { url, ... } }; older builds returned the
// record flat, so accept both rather than fail on a shape difference.
const uploadRes = $('Upload episode audio').first().json;
const uploaded = (uploadRes && uploadRes.upload) || uploadRes || {};
const audioUrl = uploaded.url || uploaded.src || uploaded.publicUrl;
if (!audioUrl) {
  throw new Error('Upload episode audio returned no url: ' + JSON.stringify(uploadRes).slice(0, 300));
}

const clips = $input.all().map((i) => i.json);
if (!clips.length) throw new Error('No clips to build - Prepare clips produced nothing.');

return clips.map((clip, i) => ({
  json: buildClipProject(config, episode, clip, audioUrl),
  pairedItem: { item: i },
}));

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug - surface the field list per clip instead
// of a generic HTTP error.
const built = $('Build project JSON').all();
return $input.all().map((res, i) => {
  const status = res.json.statusCode ?? (res.json.valid === true ? 200 : 400);
  const body = res.json.body || { ...res.json, details: res.json.errors ?? res.json.details };
  const meta = built[i].json.meta;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
      : JSON.stringify(body).slice(0, 500);
    throw new Error('Zvid rejected clip ' + meta.clipIndex + ' ("' + meta.hook + '") with HTTP ' + status + ': ' + (body.message || body.error) + '\n' + details);
  }
  return {
    json: { ...built[i].json, creditsRequired: body.creditsRequired, warnings: body.warnings || [] },
    pairedItem: { item: i },
  };
});

// Dry run: everything except the paid renders. Open each editorLink to watch
// the clip, then set dryRun to false in Config to render for real.
const cfg = $('Config').first().json;
const ep = $('Pick latest episode').first().json;
const checked = $('Check validation').all();
const total = checked.reduce((sum, c) => sum + Number(c.json.creditsRequired || 0), 0);
return $input.all().map((res, i) => {
  const d = checked[i].json;
  let editorLink = null;
  let draftId = null;
  const project = res.json && res.json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
  return {
    json: {
      dryRun: true,
      clip: d.meta.clipIndex,
      hook: d.meta.hook,
      whyItSlaps: d.meta.whyItSlaps,
      episode: ep.episodeTitle,
      startsAt: d.meta.startLabel,
      clipSeconds: d.meta.clipSeconds,
      captionCues: d.meta.captionCount,
      creditsRequired: d.creditsRequired,
      creditsRequiredThisRun: total,
      editorLink: editorLink,
      draftId: draftId,
      warnings: d.warnings,
      nextStep: editorLink
        ? 'Open editorLink to preview this clip. Set dryRun to false in Config to render every clip for real.'
        : 'Set dryRun to false in Config to render these clips.',
      payload: d.payload,
    },
    pairedItem: { item: i },
  };
});

const response = $input.first().json;
const jobId = response.jobId || response.id;
if (!jobId) throw new Error('Render submission returned no jobId. Check https://app.zvid.io before retrying.');
const { payload, ...asset } = $('Prepare render attempt').first().json;
return [{ json: { ...asset, jobId, renderStartedAt: Date.now() }, pairedItem: { item: 0 } }];

const carried = $('Attach job to clip').first().json;
const job = $input.first().json;
return [{ json: { ...carried, state: job.state, failedReason: job.failedReason || null, result: job.result || null }, pairedItem: { item: 0 } }];

const item = $input.first().json;
if (item.state === 'failed') throw new Error('The ' + item.kind + ' render failed: ' + (item.failedReason || 'no reason given'));
const timeoutMs = Number($('Config').first().json.timeoutMinutes || 20) * 60000;
if (Date.now() - Number(item.renderStartedAt) >= timeoutMs) {
  throw new Error('Render ' + item.jobId + ' timed out. It may still finish on Zvid; check https://app.zvid.io before retrying.');
}
return $input.all();

// One item per finished clip - each carries videoUrl, so the Watch node
// downloads one playable binary per clip.
const cfg = $('Config').first().json;
const ep = $('Pick latest episode').first().json;
const t = $('Read transcript').first().json;
const d = $json;
const videoUrl = typeof d.result === 'string' ? d.result : (d.result && d.result.url) || null;
if (!videoUrl) {
  throw new Error('Completed render returned no video URL for clip ' + d.meta.clipIndex);
}
return {
  json: {
    rendered: true,
    clip: d.meta.clipIndex,
    hook: d.meta.hook,
    whyItSlaps: d.meta.whyItSlaps,
    show: d.meta.showName,
    episode: ep.episodeTitle,
    episodeLink: ep.episodeLink,
    startsAt: d.meta.startLabel,
    clipSeconds: d.meta.clipSeconds,
    captionCues: d.meta.captionCount,
    momentSource: d.meta.momentSource,
    videoUrl: videoUrl,
    jobId: d.jobId,
    creditsCharged: d.creditsRequired,
    transcribedSeconds: t.transcribedSeconds,
    clipWindowSeconds: t.windowEnd,
    handle: cfg.handle,
  },
};

// Check actual bytes before paid transcription. Some hosts ignore Range.
const items = $input.all();
const maxBytes = Number($('Pick latest episode').first().json.maxBytes);
if (!Number.isFinite(maxBytes) || maxBytes < 1) throw new Error('Invalid audio sample size limit. Check Config.');
for (let i = 0; i < items.length; i++) {
  if (!items[i].binary?.data) throw new Error('The episode download returned no audio file.');
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buffer.length) throw new Error('The episode download returned an empty audio file.');
  if (buffer.length > maxBytes) {
    throw new Error('Downloaded audio is ' + buffer.length + ' bytes, above the ' + maxBytes + '-byte sample limit. The source may have ignored Range. Use a smaller audio file or a host that supports byte ranges. No transcription or render request has been made.');
  }
}
return items;

// Each deliverable owns its retry deadline; an accepted job is never resubmitted.
return $input.all().map((item, i) => ({
  json: { ...item.json, submitStartedAt: Date.now(), submitAttempts: 0 },
  pairedItem: { item: i },
}));

// Retry only an explicit HTTP 429 rejection. Timeouts/5xx may have accepted
// a paid job already, so they stop for inspection instead of creating duplicates.
const item = $input.first();
const error = item.error || item.json.error || {};
const previous = $('Prepare render attempt').first().json;
const carried = item.json.payload ? item.json : previous;
const status = Number(error.httpCode || error.statusCode || error.response?.status || error.cause?.statusCode || error.cause?.response?.status);
// n8n's task-runner serialization drops httpCode but retains its exact,
// status-specific NodeApiError message and the API response in context.data.
const serialized429 = !status && error.name === 'NodeApiError' && error.message === 'The service is receiving too many requests from you';
if (status !== 429 && !serialized429) {
  throw new Error('Render submission failed: ' + (error.description || error.message || String(error)) + '. Check https://app.zvid.io before retrying; the request may already have created a job.');
}
let body = error.response?.data || error.context?.data || error.cause?.response?.data || error.cause?.error || {};
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = {}; } }
const headers = error.response?.headers || error.cause?.response?.headers || {};
const rawRetry = headers['retry-after'] ?? body.retryAfter;
const retrySeconds = Number(rawRetry) || Math.ceil((Date.parse(rawRetry) - Date.now()) / 1000) || 30;
const waitSeconds = Math.max(30, retrySeconds);
const deadline = Number(previous.submitStartedAt) + Number($('Config').first().json.timeoutMinutes || 20) * 60000;
if (Date.now() + waitSeconds * 1000 >= deadline) {
  throw new Error('Render capacity stayed full until the submission deadline. Check https://app.zvid.io; completed assets from this run remain in Render one asset at a time.');
}
return [{ json: { ...carried, submitStartedAt: previous.submitStartedAt, submitAttempts: Number(carried.submitAttempts || 0) + 1, retrySeconds: waitSeconds }, pairedItem: { item: 0 } }];
